import sys
from collections import defaultdict, deque

def find_centroid(tree, n):
    size = [1] * (n + 1)
    parent = [None] * (n + 1)

    def dfs(node, par):
        parent[node] = par
        for neighbor in tree[node]:
            if neighbor != par:
                size[node] += dfs(neighbor, node)
        return size[node]

    dfs(1, None)

    centroid = None
    def find_centroid_node(node, par, total_size):
        nonlocal centroid
        is_centroid = True
        for neighbor in tree[node]:
            if neighbor != par:
                if size[neighbor] > total_size // 2:
                    is_centroid = False
                find_centroid_node(neighbor, node, total_size)
        if is_centroid and (total_size - size[node]) <= total_size // 2:
            centroid = node

    find_centroid_node(1, None, size[1])
    return centroid

def bfs_distance(tree, start):
    queue = deque([start])
    distance = [-1] * (len(tree) + 1)
    distance[start] = 0
    while queue:
        node = queue.popleft()
        for neighbor in tree[node]:
            if distance[neighbor] == -1:
                distance[neighbor] = distance[node] + 1
                queue.append(neighbor)
    return distance

def max_edges_covered(n, edges):
    tree = defaultdict(list)
    for a, b in edges:
        tree[a].append(b)
        tree[b].append(a)

    centroid = find_centroid(tree, n)

    distances = []
    for neighbor in tree[centroid]:
        distances.append(bfs_distance(tree, neighbor))

    max_edges = 0
    best_a, best_b, best_c = -1, -1, -1

    for i in range(len(distances)):
        for j in range(i + 1, len(distances)):
            for k in range(j + 1, len(distances)):
                current_edges = 0
                for node in range(1, n + 1):
                    min_dist = min(distances[i][node], distances[j][node], distances[k][node])
                    if min_dist != -1:
                        current_edges += 1
                if current_edges > max_edges:
                    max_edges = current_edges
                    best_a, best_b, best_c = distances[i].index(max(distances[i])), distances[j].index(max(distances[j])), distances[k].index(max(distances[k]))

    return max_edges, best_a, best_b, best_c

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    edges = [(int(data[2*i+1]), int(data[2*i+2])) for i in range(n-1)]

    res, a, b, c = max_edges_covered(n, edges)

    print(res)
